	id_senaltc public.senaltc.id%type;
	id_sistemacontrol public.sistemacontrol.id%type;
	id_componentescgen_tc public.componentesc.id%type;
	id_elementoscorigen_tc public.elementosc.id%type;
	id_componentescorigen_tc public.componentesc.id%type;
	id_elementoscorigen_dyes public.elementosc.id%type;
	id_componentegen_dyes public.componentesc.id%type;
	id_componentescorigen_dyes public.componentesc.id%type;
	id_senaldyes public.senaldyes.id%type;
	id_senaldyessc public.senaldyessc.id%type;
	id_tipopuntoprotocolo public.tipopuntoprotocolo.id%type;
	id_senaltcsc public.senaltcsc.id%type;
	indice int;
begin
  	FOR indice in 1 .. array_length(tag_senaltcsc, 1) loop
		-- Obtiene el ID de la señal del diccionario de señales de telecontrol
		select
			id into id_senaltc
		from
			public.senaltc stc
		where
			stc.codigo = codigotc_senaltcsc[indice];
		--Obtiene el ID del sistema de control
		select
			sc.id into id_sistemacontrol
		from
			public.sistemacontrol sc
		left join
			public.versionsc vsc
		on 
			vsc.id = sc.idversionsc
		where
			sc.nemonico = sistemacontrol_senaltcsc[indice]
			and vsc."version" = versionsc_senaltcsc[indice];
		-- Obtiene el ID del componente de inventario del sc que genera la señal de telecontrol
		select
			id into id_componentescgen_tc
		from
			public.componentesc cpsc
		where
			cpsc.codigo = componentescgen_tc_senaltcsc[indice]
			and cpsc.idsistemacontrol = id_sistemacontrol;
		-- Origen de la señal de telecontrol
		-- El origen puede ser componente o elemento.
		IF elementoscorigen_tc_senaltcsc[indice] = '' THEN
			-- La señal es de alarma interna (procede de un componente) -> i
			id_elementoscorigen_tc = null;
			select
				cpsc.id into id_componentescorigen_tc
			from
				public.componentesc cpsc
			where
				cpsc.codigo = componentescorigen_tc_senaltcsc[indice]
				and cpsc.idsistemacontrol = id_sistemacontrol;
		else
			-- La señal procede de un elemento.
			id_componentescorigen_tc = null;
			select
				esc.id into id_elementoscorigen_tc
			from
				public.elementosc esc
			left join
				public.componentesc csc
			on
				csc.id = esc.idcomponentesc
			where
				esc.codigo = elementoscorigen_tc_senaltcsc[indice]
				and csc.idsistemacontrol = id_sistemacontrol;
		end if;
		-- Origen de la señal dyes
		-- El origen puede ser componente o elemento.
		IF elementodyesscorigen_senaltcsc[indice] = '' THEN
			-- La señal es de alarma interna (procede de un componente) -> i
			id_elementoscorigen_dyes = null;
			select
				cpsc.id into id_componentescorigen_dyes
			from
				public.componentesc cpsc
			where
				cpsc.codigo = componentedyesscorigen_senaltcsc[indice]
				and cpsc.idsistemacontrol = id_sistemacontrol;
		else
			-- La señal procede de un elemento.
			id_componentescorigen_dyes = null;
			select
				esc.id into id_elementoscorigen_dyes
			from
				public.elementosc esc
			left join
				public.componentesc csc
			on
				csc.id = esc.idcomponentesc
			where
				esc.codigo = elementodyesscorigen_senaltcsc[indice]
				and csc.idsistemacontrol = id_sistemacontrol;
		end if;
		-- Componente generador de la señal DYES
		select
			cpsc.id into id_componentegen_dyes
		from
			public.componentesc cpsc
		where
			cpsc.codigo = componentegen_dyes[indice]
			and cpsc.idsistemacontrol = id_sistemacontrol;
		-- Obtiene la señal DYES de diccionario
		select
			sd.id into id_senaldyes
		from
			public.senaldyes sd
		left join
			public.paginadyes pd
		on
			pd.id = sd.idpaginadyes
		where
			pd.codigo = paginadyes_senaltcsc[indice]
			and sd.clavedyes = clavedyes_senaltcsc[indice];
		-- Obtiene la señal del inventario del componente generador con página y clave especificada
		select
			sdsc.id into id_senaldyessc
		from
			public.senaldyessc sdsc
		where
			--(
			--	((id_componentescorigen_dyes is null) and (sdsc.idelementoscorigen = id_elementoscorigen_dyes)) or
			-- 	((id_elementoscorigen_dyes is null) and (sdsc.idcomponentescorigen = id_componentescorigen_dyes))
			--)
			sdsc.idcomponentescgen = id_componentegen_dyes
			and sdsc.idsenaldyes = id_senaldyes;
		raise info 'ID elemento origen dyes: %, ID componente origen dyes: %, pagina: % clave: % idsenaldyes: % idsenaldyessc: %',id_elementoscorigen_dyes, id_componentescorigen_dyes, paginadyes_senaltcsc[indice], clavedyes_senaltcsc[indice], id_senaldyes, id_senaldyessc;
		-- Obtiene el ID del tipo de punto de protocolo
		select
			tpp.id into id_tipopuntoprotocolo
		from
			public.tipopuntoprotocolo tpp
		left join
			public.protocolo pr
		on
			pr.id = tpp.idprotocolo
		where
			pr.codigo = protocolo_senaltcsc[indice]
			and tpp.tipo = tipopuntoprotocolo_senaltcsc[indice];
		-- Obtiene el ID de la señal de telecontrol (para comprobar si existe ya en la BBDD
		select
			stsc.id into id_senaltcsc
		from
			public.senaltcsc stsc
		where
			stsc.idsenaltc = id_senaltc
			and stsc.idcomponentescgen  = id_componentescgen_tc
			and stsc.idcomponentescorigen = id_componentescorigen_tc
			and stsc.idelementoscorigen = id_elementoscorigen_tc
			and stsc.idsenaldyessc = id_senaldyessc;
		-- Inserta el registro en la tabla
		raise info 'Num: %, ID Senal DYES: %, ID Elemento Origen TC: %, ID componente origen TC: %, ID Elemento Origen DYES: %, ID componente origen DYES: %, ID Señal DYESSC: %',indice,id_senaldyes, id_elementoscorigen_tc, id_componentescorigen_tc,  id_elementoscorigen_dyes, id_componentescorigen_dyes, id_senaldyessc;
		if id_senaltcsc is null then
			-- Inserta la señal del inventario de señales de telecontrol
			INSERT INTO public.senaltcsc(
				tag,
				idsenaltc,
				idcomponentescgen,
				idelementoscorigen,
				idcomponentescorigen,
				idsenaldyessc,
				numpuntoprotocolosc,
				idtipopuntoprotocolo)
			VALUES(
				tag_senaltcsc[indice], 
				id_senaltc,
				id_componentescgen_tc,
				id_elementoscorigen_tc,
				id_componentescorigen_tc,
				id_senaldyessc,
				numpunto_senaltcsc[indice],
				id_tipopuntoprotocolo);
		end if;
	end loop;
end;
$body$ LANGUAGE plpgsql;

