	sistemacontrol_entradasumandosc text[] := array[
		'BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4','BEN4',
